    internal static int AtGeo(emon.Port.Cells res, int sigs) {
        // Nine figures and seals that are not provisional figures, placed against three candidates; their outcomes into `res`.
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells assets = emon.Port.NewCells();
        emon.Port.Cells uses = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells box = emon.Port.NewCells();
        emon.Port.Buf cbytes = emon.Port.NewBuf();
        emon.Port.Buf abytes = emon.Port.NewBuf();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        AtBytes(cbytes, 4, 97);
        AtBytes(cbytes, 4, 98);
        // C0 and C1 are images, C2 a page-sized one (its pixels are not made: part)
        AtCand(cand, 1, 10000, 10000, 30000, 30000, 0, 0, 4, 1);
        AtCand(cand, 1, 50000, 10000, 70000, 30000, 0, 4, 4, 2);
        AtCand(cand, 1, 100000, 100000, 120000, 120000, 2, 0, 0, 0);
        AtFigAt(nodes, regions, Model.NkFigure(), Model.FgUnknown(), 1, 10000, 10000, 30000, 30000);
        AtFigAt(nodes, regions, Model.NkFigure(), Model.FgUnknown(), 1, 12000, 12000, 20000, 20000);
        AtFigAt(nodes, regions, Model.NkFigure(), Model.FgUnknown(), 1, 20000, 10000, 60000, 30000);
        AtFigAt(nodes, regions, Model.NkFigure(), Model.FgUnknown(), 1, 200000, 200000, 220000, 220000);
        AtFigAt(nodes, regions, Model.NkSeal(), Model.SlSignature(), 1, 10000, 10000, 30000, 30000);
        AtFigAt(nodes, regions, Model.NkSeal(), Model.SlDigitalSignature(), 1, 10000, 10000, 30000, 30000);
        AtFigAt(nodes, regions, Model.NkSeal(), Model.SlStamp(), 1, 50000, 10000, 70000, 30000);
        AtFigAt(nodes, regions, Model.NkFigure(), Model.FgUnknown(), 1, 100000, 100000, 120000, 120000);
        AtFigAt(nodes, regions, Model.NkFigure(), Model.FgUnknown(), -1, 0, 0, 0, 0);
        AtBox(box);
        Asset.AsRun(nodes, attrs, regions, cand, cbytes, assets, uses, abytes, 8, 100, sigs, box);
        emon.Port.CellsDrop(res, 0);
        int n = 1;
        while (n <= 9) {
            emon.Port.CellsPush(res, Model.NodeAttrIntOr(nodes, attrs, n, Model.FkAsset(), -1));
            emon.Port.CellsPush(res, Model.NodeAttrIntOr(nodes, attrs, n, Model.FkNoasset(), -1));
            n += 1;
        }
        return 0;
    }
    [Xunit.Fact]
    public static void TestANodeIsTheImageItIsOrSaysWhyNot() {
        emon.Port.Cells res = emon.Port.NewCells();
        AtGeo(res, 0);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 0), 0, "a figure that is one whole image gets it (asset 0)");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 3), Model.NzPart(), "a figure inside one image's box is part of it");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 5), Model.NzComposite(), "a figure over two images is a composite");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 7), Model.NzVector(), "a figure with no image under it is vector");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 9), Model.NzWithheld(), "a signature seal is withheld");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 10), -1, "a digital signature has no pixels and no field");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 11), -1, "no reason either");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 12), 1, "a stamp seal that is one image gets it (asset 1)");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 15), Model.NzPart(), "an image the size of a page is never an asset at images");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 17), Model.NzVector(), "a node with no region is vector");
        // with asset-signatures on, the signature seal is the image
        AtGeo(res, 1);
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 8), 0, "a signature seal gets the image when signatures are on");
        emon.Testport.AssertEq(emon.Port.CellsAt(res, 9), -1, "and has no reason");
    }
